head.script:
// 테스트 설명, 유효성 값 설정
//  ★ Method _4 : mergeOptionStr = byrestricrow (가로 제한 병합). description 은 _1 과 동일.
scwin.tData = {
    "description" : "[gridView > M > mergeCellsFixedRows]<br/>GridView 컴포넌트의 mergeCellsFixedRows 속성을 설정합니다.",
    "validation" : [
        "mergeOptionStr 'byrestricrow' 설정 시 윗쪽 Row 가 병합된 범위 내에서 'byrow' 방식으로 병합을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — byrestricrow(가로 제한) 전용. 고정 Row 4행(col1~col10)의 계층형 가로 cascade. (P_FR_4 데이터와 동일)
//  (왼쪽으로 갈수록 큰 그룹 → 오른쪽으로 갈수록 잘게 쪼개지는 가로 계층. 4행 전부 fixedRow 고정 영역에 둠)
//    행0 : 10000 ×10                          (1x10 한 그룹)
//    행1 : 220000 ×5 / 320000 ×5              (경계 col5|col6)
//    행2 : 630000 ×4 / 730000 ×3 / 830000 ×3
//    행3 : 1240000 ×3 / 1340000 ×2 / 1440000 ×3 / 1540000 ×2
//   ── byrestricrow 제한 시연 ──
//    아래 행의 가로병합이 '윗 행이 병합된 범위' 를 넘지 못한다.
//    예) 행2 의 730000(원래 col5~col7) 은 윗 행(행1)의 경계 col5|col6 때문에 col5 단독 + col6~col7 로 잘려 병합된다.
//   ── 세로 스크롤로 고정 Row 인지 ──
//    위 4행(고정 Row 영역) 뒤에 비고정 행(행별 서로 다른 값=미병합)을 6행 더 추가하여 총 10행으로 만든다.
//    grid height 가 작아 일부 행만 보이므로 세로 스크롤이 생기고, 스크롤해도 상단 4행(고정 Row)은 고정으로 남는다.
scwin.makeData = function () {
    // mergeByRestricCol.xml 의 첫 루프(헤더 계층) = 10열 × 4행 = 40개 값 (고정 Row 영역, P_FR_4 동일)
    let data1 = [];
    for (let f = 0; f < 10 * 4; f++) {
        let rx = Math.floor(f / 10) + 1;
        let zx = rx + 10 * Math.floor(f / (10 / rx));
        data1.push(zx * 10000);
    }
    // 비고정 행 추가 : 행별·열별 서로 다른 값(미병합)으로 6행(10열×6=60개) append → 총 10행/100개 값.
    //  고정 Row 영역(상단 4행)의 byrestricrow 제한 시연에 영향을 주지 않도록 모두 고유 값으로 채운다.
    for (let r = 5; r <= 10; r++) {
        for (let c = 1; c <= 10; c++) {
            data1.push(r * 100 + c); // 예: 501,502,...,1010 (모두 서로 다른 값 → 미병합)
        }
    }
    return data1;
}



// comp 생성 : 10열 그리드를 동적 생성하고 fixedRow=4(상단 4행 전부 고정) 영역에 병합 대상을 둔다. (P_FR_4 와 동일 데이터·target)
//  ★ Method 샘플이므로 mergeCellsFixedRows 는 생성 attribute 로 주지 않고, par_mergeOptionStr 선택 후 mergeCellsFixedRows 버튼으로 적용한다.
//  ★ 비고정 6행을 더해 총 10행 + grid height 260px → 세로 스크롤이 생기며, 스크롤해도 상단 4행(고정 Row)은 상단에 고정으로 남는다.
//  ★ rowMerge 는 부여하지 않음 — 부여하면 초기 byrow 자동병합이 byrestricrow 결과와 겹쳐 렌더가 깨지므로 메소드만으로 적용.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (Target 재생성 시 동일 id 재생성이 무시되지 않도록 먼저 제거)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="고정 4행 계층 데이터(mergeByRestricCol 1~4행)+비고정 6행. par_mergeOptionStr 선택 후 mergeCellsFixedRows 버튼으로 적용. 세로 스크롤하면 상단 4행(고정 Row)이 고정으로 남음. byrestricrow=아래 행 가로병합이 윗 행 병합 범위를 넘지 못함(예: 행2 730000 이 col5 단독+col6~col7 로 잘림)"', '', 'label1');

    // 10열 DataList 인라인 생성 (공통 createDynamicDataList 는 col1~col4 만 정의하므로 직접 생성)
    let dlNS = $c.gcm.getNameSpace();
    let strDL = '';
    strDL += '<w2:dataList ' + dlNS + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDL += '<w2:columnInfo>';
    for (let i = 1; i <= 10; i++) {
        strDL += '<w2:column id="col' + i + '" name="col' + i + '" dataType="text"></w2:column>';
    }
    strDL += '</w2:columnInfo>';
    strDL += '<w2:data use="true"></w2:data>';
    strDL += '</w2:dataList>';
    $p.data.create(strDL);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin["dlt_bind"] = arrDC[arrDC.length - 1];

    // 1~4행 계층 데이터 + 비고정 6행 적재 (flat array → 10열씩 10행)
    dlt_bind.setData(scwin.makeData());

    // grid 생성 — fixedRow=4 로 상단 4행 전부 고정(mergeCellsFixedRows 는 고정 Row 영역만 병합 대상)
    let properties = {
        dataList: "data:" + dlt_bind.id,
        fixedRow: 4
    };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (mergeCellsFixedRows 속성은 부여하지 않음 → 버튼 클릭 시 메소드로 적용)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:680px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedRows byrestricrow sample (고정 4행 / 가로 계층)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 1; i <= 10; i++) {
        strTarget += '<w2:column width="65" style="" inputType="text" id="column' + i + '" value="col' + i + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    for (let i = 1; i <= 10; i++) {
        strTarget += '<w2:column width="65" style="" inputType="text" id="col' + i + '" value=""></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// mergeCellsFixedRows 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCellsFixedRows(mergeOptionStr) 호출
//  · options(선택) 파라미터는 별도 샘플에서 다루므로 여기서는 생략한다.
scwin.btn_mergeCellsFixedRows_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCellsFixedRows(mode);

    bottom.setReturnValue("[옵션] mergeCellsFixedRows=" + target1.options.mergeCellsFixedRows + " / mergeOptionStr='" + mode + "'");
    bottom.setReturnValue("[고정 Row 수] fixedRow : " + (target1.options.fixedRow || 0));

    scwin.printMergeState(bottom, mode);
}



// 병합 상태 확인 : 고정 Row 영역 Body td 의 colSpan 을 읽어 각 행의 가로병합 그룹을 출력하고,
//  byrestricrow 제한(윗 행 병합 범위) 으로 잘려 병합되는 경계를 명확히 출력한다.
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
scwin.printMergeState = function (bottom, mode) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    // 행별로 가로병합(colSpan>1) 그룹을 모아 출력
    let rowMap = {};
    let seen = {};
    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === "none" || td.offsetParent === null) continue;
        let cs = td.colSpan || 1;
        if (cs <= 1) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;
        if (!rowMap[r]) rowMap[r] = [];
        let val = (td.textContent || "").trim();
        rowMap[r].push("col" + (c + 1) + "~col" + (c + cs) + "='" + val + "'");
    }

    let rows = Object.keys(rowMap).map(Number).sort(function (a, b) { return a - b; });
    bottom.setReturnValue("가로병합이 있는 행 " + rows.length + "개");
    if (rows.length === 0) {
        bottom.setReturnValue("가로병합된 셀 없음");
    } else {
        for (let i = 0; i < rows.length; i++) {
            bottom.setReturnValue("➡ 행" + rows[i] + " : " + rowMap[rows[i]].join(" / "));
        }
    }

    // byrestricrow 제한 경계 판정 : 행2 의 730000(원래 col5~col7)이 윗 행(행1)의 경계 col5|col6 때문에
    //  col5 단독 + col6~col7 로 잘려 병합되는지(가로병합이 col5~col7 한 덩어리로 넘어가지 않는지) 확인.
    if (mode === "byrestricrow") {
        let restricted = scwin.isAnchor(gid, 2, 5);   // 행2 col6(index5)이 별도 가로병합 그룹 시작 anchor = 윗 행 경계로 잘림
        bottom.setReturnValue("[제한 경계] 행2 730000 이 윗 행(행1) 경계 col5|col6 로 제한되어 col5 단독 + col6~col7 로 잘려 병합 : " + restricted);
    }
}



// 공통 : colIndex 컬럼에서 row 행이 '병합 시작(anchor)' 인지 여부 (표시되는 td 가 존재하면 anchor = 별도 그룹 시작)
scwin.isAnchor = function (gid, row, colIndex) {
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_" + row + "_" + colIndex + "']");
    for (let i = 0; i < tds.length; i++) {
        if (getComputedStyle(tds[i]).display !== 'none' && tds[i].offsetParent !== null) return true;
    }
    return false;
}
